/* ------------------------------------------------------------------ */
/*  Scroll Reveal                                                     */
/* ------------------------------------------------------------------ */
const Reveal = ({ children, className = "", delay = 0, variant = "up" }) => {
  const ref = useRef(null);
  const [inView, setInView] = useState(false);

  useEffect(() => {
    const el = ref.current;
    if (!el) return;
    const obs = new IntersectionObserver(
      ([entry]) => {
        if (entry.isIntersecting) {
          setInView(true);
          obs.disconnect();
        }
      },
      { threshold: 0.15 }
    );
    obs.observe(el);
    return () => obs.disconnect();
  }, []);

  const base = variant === "scale" ? "kc-scale-in" : "kc-reveal";

  return (
    <div
      ref={ref}
      className={`${base} ${inView ? "kc-in" : ""} ${className}`}
      style={{ transitionDelay: `${delay}ms` }}
    >
      {children}
    </div>
  );
};

/* ------------------------------------------------------------------ */
/*  Word-by-word text reveal                                          */
/* ------------------------------------------------------------------ */
const WordReveal = ({ text, start, baseDelay = 0, stagger = 90, className = "" }) => {
  const words = text.split(" ");
  return (
    <span className={className}>
      {words.map((w, i) => (
        <React.Fragment key={i}>
          <span className="kc-word-mask">
            <span
              className={`kc-word-inner ${start ? "kc-in" : ""}`}
              style={{ transitionDelay: `${baseDelay + i * stagger}ms` }}
            >
              {w}
            </span>
          </span>
          {i < words.length - 1 ? " " : ""}
        </React.Fragment>
      ))}
    </span>
  );
};

