/* ------------------------------------------------------------------ */
/*  Hooks: Scroll Progress, Countdown, Horizontal Carousel dots       */
/* ------------------------------------------------------------------ */
const useScrollProgress = () => {
  const [pct, setPct] = useState(0);
  useEffect(() => {
    const onScroll = () => {
      const h = document.documentElement;
      const max = h.scrollHeight - h.clientHeight || 1;
      setPct(Math.min(1, Math.max(0, h.scrollTop / max)));
    };
    onScroll();
    window.addEventListener("scroll", onScroll, { passive: true });
    return () => window.removeEventListener("scroll", onScroll);
  }, []);
  return pct;
};

const useCountdown = () => {
  // Offset: 1 day (24h) + 19 hours = 43 hours total
  const target = useRef(
    Date.now() + 
    1000 * 60 * 60 * 24 * 1 + // 1 day
    1000 * 60 * 60 * 19       // 19 hours
  ).current;

  const [left, setLeft] = useState(target - Date.now());

  useEffect(() => {
    const id = setInterval(() => setLeft(Math.max(0, target - Date.now())), 1000);
    return () => clearInterval(id);
  }, [target]);

  return {
    d: Math.floor(left / 86400000),
    h: Math.floor((left / 3600000) % 24),
    m: Math.floor((left / 60000) % 60),
    s: Math.floor((left / 1000) % 60),
  };
};

const useCarouselDots = (count) => {
  const containerRef = useRef(null);
  const [active, setActive] = useState(0);
  const onScroll = useCallback(() => {
    const el = containerRef.current;
    if (!el || count === 0) return;
    const cardWidth = el.scrollWidth / count;
    const idx = Math.round(el.scrollLeft / cardWidth);
    setActive(Math.min(count - 1, Math.max(0, idx)));
  }, [count]);
  return { containerRef, active, onScroll };
};

/* Count-up number, triggers once in view — small professional touch */
const CountUp = ({ to, className = "", suffix = "" }) => {
  const ref = useRef(null);
  const [val, setVal] = useState(0);
  useEffect(() => {
    const el = ref.current;
    if (!el) return;
    const obs = new IntersectionObserver(
      ([entry]) => {
        if (entry.isIntersecting) {
          const start = performance.now();
          const dur = 1100;
          const step = (t) => {
            const p = Math.min(1, (t - start) / dur);
            setVal(Math.round(to * (1 - Math.pow(1 - p, 3))));
            if (p < 1) requestAnimationFrame(step);
          };
          requestAnimationFrame(step);
          obs.disconnect();
        }
      },
      { threshold: 0.4 }
    );
    obs.observe(el);
    return () => obs.disconnect();
  }, [to]);
  return (
    <span ref={ref} className={className}>
      {String(val).padStart(2, "0")}
      {suffix}
    </span>
  );
};

