/* ------------------------------------------------------------------ */
/*  Scroll Progress Wrapper — Isolates scroll updates                 */
/* ------------------------------------------------------------------ */
const ScrollProgressWrapper = ({ loading, menuOpen, onRegister }) => {
  const pct = useScrollProgress();
  const showStickyBar = !loading && pct > 0.045 && pct < 0.97 && !menuOpen;
  
  return (
    <>
      <RouteLine pct={pct} />
      <MiniKing pct={pct} ready={!loading} />
      <StickyMobileBar visible={showStickyBar} onRegister={onRegister} />
    </>
  );
};

/* ------------------------------------------------------------------ */
/*  Countdown Wrapper — Isolates countdown timer updates              */
/* ------------------------------------------------------------------ */
const CountdownWrapper = ({ ctaRef, onRegister }) => {
  const ctdown = useCountdown();
  
  return <FinalCta ctaRef={ctaRef} ctdown={ctdown} onRegister={onRegister} />;
};

/* ------------------------------------------------------------------ */
/*  Main Component                                                    */
/* ------------------------------------------------------------------ */
const KingsCodeAcademy = () => {
  const [loading, setLoading] = useState(true);
  const [heroIn, setHeroIn] = useState(false);
  const [showRegistration, setShowRegistration] = useState(false);
  const [menuOpen, setMenuOpen] = useState(false);
  const ctaRef = useRef(null);

  useEffect(() => {
    const params = new URLSearchParams(window.location.search);
    const reference = params.get('reference') || params.get('trxref');
    if (!reference || params.get('status') === 'cancelled') return;

    verifyPaymentWithRetry(reference)
      .catch((error) => console.error('Paystack redirect verification failed:', error))
      .finally(() => {
        window.history.replaceState({}, document.title, window.location.pathname + window.location.hash);
      });
  }, []);

  const handleLoadingDone = useCallback(() => {
    setLoading(false);
    setTimeout(() => setHeroIn(true), 120);
  }, []);

  const scrollToId = useCallback((id) => {
    setMenuOpen(false);
    if (id === "top") {
      window.scrollTo({ top: 0, behavior: "smooth" });
      return;
    }
    const el = document.getElementById(id);
    el?.scrollIntoView({ behavior: "smooth", block: "start" });
  }, []);

  const openRegistration = useCallback(() => {
    setMenuOpen(false);
    setShowRegistration(true);
  }, []);

  return (
    <div className="kc-root relative">
      <GlobalStyle />
      {loading && <Loader onDone={handleLoadingDone} />}
      
      {/* Isolated scroll progress components */}
      <ScrollProgressWrapper loading={loading} menuOpen={menuOpen} onRegister={openRegistration} />

      {/* Background Grid */}
      <div className="kc-grid-bg" />
      <div className="fixed inset-0 pointer-events-none overflow-hidden z-0">
        <div className="absolute top-[-10%] left-1/2 -translate-x-1/2 w-[700px] h-[700px] rounded-full bg-[#4C1D95]/15 blur-[150px]" />
        <div className="absolute bottom-[-10%] right-[-10%] w-[600px] h-[600px] rounded-full bg-[#C08A45]/10 blur-[150px]" />
      </div>

      <Header
        onRegister={openRegistration}
        menuOpen={menuOpen}
        setMenuOpen={setMenuOpen}
        onNavigate={scrollToId}
      />
      <MobileMenu open={menuOpen} onClose={() => setMenuOpen(false)} onNavigate={scrollToId} onRegister={openRegistration} />

      <Hero heroIn={heroIn} onRegister={openRegistration} onNavigate={scrollToId} />
      <IntroSections />
      <CoursesSection />
      <NavigatorsSection />
      <TestimonialsSection />
      
      {/* Isolated countdown timer component */}
      <CountdownWrapper ctaRef={ctaRef} onRegister={openRegistration} />
      
      <Footer onNavigate={scrollToId} />
      <RegistrationModal open={showRegistration} onClose={() => setShowRegistration(false)} />
    </div>
  );
};

export default KingsCodeAcademy;
